// node --test tests of site/assets/js/models/learning.js
// Compares against site/tests/golden/learning.json generated by scripts/site/golden_learning.py
// and exercises edge cases and validation failures.

import test from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, join } from 'node:path';

import * as M from '../assets/js/models/learning.js';

const here = dirname(fileURLToPath(import.meta.url));
const golden = JSON.parse(readFileSync(join(here, 'golden', 'learning.json'), 'utf8'));

const TOLERANCE = 1e-4;

function assertCloseArray(actual, expected, msg, tol = TOLERANCE) {
  assert.equal(actual.length, expected.length, `${msg}: length mismatch (${actual.length} vs ${expected.length})`);
  for (let i = 0; i < actual.length; i++) {
    const diff = Math.abs(actual[i] - expected[i]);
    assert.ok(diff <= tol, `${msg} [index ${i}]: actual ${actual[i]} vs expected ${expected[i]} (diff ${diff} > tol ${tol})`);
  }
}

// ---------------------------------------------------------------------------
// 1. Golden comparison for all 13 classes
// ---------------------------------------------------------------------------

for (const className of M.LEARNING_CLASSES) {
  test(`learning class ${className} matches golden simulation`, () => {
    const g = golden.classes[className];
    assert.ok(g, `missing golden entry for ${className}`);

    const sim = M.simulateLearningTrace({
      className,
      params: g.params,
      meta: g.meta,
      pre_spikes: g.pre_spikes,
      post_spikes: g.post_spikes,
    });

    // Check final weights
    assertCloseArray(sim.final_weights, g.final_weights, `${className} final weights`);

    // Check mean weights trajectory
    assertCloseArray(sim.history_mean_weights, g.history_mean_weights, `${className} mean weights`);

    // Check intermediate steps
    for (let t = 0; t < g.history_weights.length; t++) {
      assertCloseArray(sim.history_weights[t], g.history_weights[t], `${className} step ${t}`);
    }
  });
}

// ---------------------------------------------------------------------------
// 2. Golden comparison for bound curves and trajectories
// ---------------------------------------------------------------------------

test('bound curves match golden reference', () => {
  const { curves } = golden.bounds;
  const { w, w_min, w_max, soft_bound, hard_bound, no_bound } = curves;

  for (let i = 0; i < w.length; i++) {
    const wi = w[i];
    const s = M.softBound(wi, w_min, w_max);
    const h = M.hardBound(wi, w_min, w_max);
    const n = M.noBound(wi, w_min, w_max);

    assert.ok(Math.abs(s - soft_bound[i]) <= 1e-5, `soft_bound at ${wi}: ${s} vs ${soft_bound[i]}`);
    assert.equal(h, hard_bound[i], `hard_bound at ${wi}: ${h} vs ${hard_bound[i]}`);
    assert.equal(n, no_bound[i], `no_bound at ${wi}: ${n} vs ${no_bound[i]}`);
  }
});

test('bound trajectories match golden potentiation and depression simulation', () => {
  const { trajectory } = golden.bounds;
  const { w0, dw_plus, dw_minus, n_plus, n_minus, w_min, w_max, trajectories } = trajectory;

  for (const boundName of ['soft_bound', 'hard_bound', 'no_bound']) {
    const actual = M.simulateBoundTrajectory({
      w0,
      dw_plus,
      dw_minus,
      n_plus,
      n_minus,
      w_min,
      w_max,
      bound: boundName,
    });
    assertCloseArray(actual, trajectories[boundName], `trajectory for ${boundName}`);
  }
});

// soft_bound is the quadratic (w - w_min)(w_max - w), so it has NO interior
// fixed point: one-sided pulses drive the weight to the boundary, and a
// symmetric potentiation/depression cycle returns it to ~w0. This is the
// behaviour the learn-bounds hero shows (the bead is not "stuck" mid-rail).
test('soft_bound has no interior fixed point (converges to the boundary)', () => {
  const base = { w0: 0.5, dw_plus: 0.05, dw_minus: 0.05, w_min: 0, w_max: 1 };
  // pure potentiation -> w_max
  const pot = M.simulateBoundTrajectory({ ...base, bound: 'soft_bound', n_plus: 500, n_minus: 0 });
  assert.ok(Math.abs(pot[pot.length - 1] - 1) < 1e-3, `soft potentiation should reach w_max, got ${pot[pot.length - 1]}`);
  // pure depression -> w_min
  const dep = M.simulateBoundTrajectory({ ...base, bound: 'soft_bound', n_plus: 0, n_minus: 500 });
  assert.ok(Math.abs(dep[dep.length - 1] - 0) < 1e-3, `soft depression should reach w_min, got ${dep[dep.length - 1]}`);
  // symmetric cycle (the plate default) -> returns to ~w0, not an interior w*
  const cyc = M.simulateBoundTrajectory({ ...base, bound: 'soft_bound', n_plus: 20, n_minus: 20 });
  const end = cyc[cyc.length - 1];
  assert.ok(Math.abs(end - 0.5) < 0.05, `soft symmetric cycle should return near w0=0.5, got ${end}`);
});

// ---------------------------------------------------------------------------
// 3. Edge and failure cases
// ---------------------------------------------------------------------------

test('stepTrace validates tau_s and dt', () => {
  assert.throws(() => M.stepTrace(0.5, 1, { tau_s: 0, dt: 1 }), /tau_s must be > 0, got 0/);
  assert.throws(() => M.stepTrace(0.5, 1, { tau_s: -5, dt: 1 }), /tau_s must be > 0, got -5/);
  assert.throws(() => M.stepTrace(0.5, 1, { tau_s: 10, dt: 0 }), /dt must be > 0, got 0/);
  assert.throws(() => M.stepTrace(0.5, 1, { tau_s: NaN, dt: 1 }), /tau_s must be a finite number/);
});

test('dopamineStep validates tau_dopamine and payoff', () => {
  assert.throws(() => M.dopamineStep({ dopamine_concentration: 1, tau_dopamine: 0, payoff: 1 }), /tau_dopamine must be > 0, got 0/);
  assert.throws(() => M.dopamineStep({ dopamine_concentration: 1, tau_dopamine: 10, payoff: Infinity }), /payoff must be a finite number/);
});

test('rstdpStep validates tau_c and dimension match', () => {
  assert.throws(() => M.rstdpStep({ c: [0, 0], dw: [0, 0], tau_c: 0, dopamine_concentration: 1 }), /tau_c must be > 0, got 0/);
  assert.throws(() => M.rstdpStep({ c: [0], dw: [0, 0], tau_c: 10, dopamine_concentration: 1 }), /eligibility trace length 1 != dw length 2/);
});

test('boundFn rejects unknown bound name', () => {
  assert.throws(() => M.boundFn('invalid_bound'), /unknown bound "invalid_bound"/);
});

test('simulateBoundTrajectory validates bounds ordering', () => {
  assert.throws(() => M.simulateBoundTrajectory({ w0: 0.5, dw_plus: 0.1, dw_minus: 0.1, n_plus: 5, n_minus: 5, w_min: 1.0, w_max: 0.5 }), /w_min \(1\) must be strictly less than w_max \(0.5\)/);
});

test('simpleStdpDw rejects mismatched dimensions', () => {
  assert.throws(
    () => M.simpleStdpDw({
      weights: [0.5, 0.5],
      pre_spike: [1, 0],
      post_spike: [1, 0],
      pre_trace: [0.1, 0.2],
      post_trace: [0.1, 0.2],
      a_plus: 0.01,
      a_minus: 0.01,
    }),
    /weights length 2 != nSrc\*nDst \(4\)/
  );
});

test('sparseStdpDw rejects mismatched index lengths', () => {
  assert.throws(
    () => M.sparseStdpDw({
      weights: [0.5, 0.5],
      src_idx: [0],
      dst_idx: [0, 1],
      pre_spike: [1, 0],
      post_spike: [1, 0],
      pre_trace: [0.1, 0.2],
      post_trace: [0.1, 0.2],
      a_plus: 0.01,
      a_minus: 0.01,
    }),
    /sparse index lengths/
  );
});

test('one2oneStdpDw rejects mismatched pre/post sizes', () => {
  assert.throws(
    () => M.one2oneStdpDw({
      weights: [0.5, 0.5],
      pre_spike: [1],
      post_spike: [1, 0],
      pre_trace: [0.1, 0.2],
      post_trace: [0.1, 0.2],
      a_plus: 0.01,
      a_minus: 0.01,
    }),
    /pre\/post spike length/
  );
});

test('conv2dStdpDw rejects mismatched kernel and spatial sizes', () => {
  assert.throws(
    () => M.conv2dStdpDw({
      weights: [0.5, 0.5],
      srcH: 4, srcW: 4, dstH: 2, dstW: 2, kh: 3, kw: 3,
      pre_spike: new Array(16).fill(0),
      post_spike: new Array(4).fill(0),
      pre_trace: new Array(16).fill(0),
      post_trace: new Array(4).fill(0),
      a_plus: 0.01, a_minus: 0.01,
    }),
    /conv2d kernel weights length 2 != kh\*kw \(9\)/
  );
});

test('local2dStdpDw rejects mismatched local weights size', () => {
  assert.throws(
    () => M.local2dStdpDw({
      weights: new Array(10).fill(0.5),
      srcH: 4, srcW: 4, dstH: 2, dstW: 2, kh: 3, kw: 3,
      pre_spike: new Array(16).fill(0),
      post_spike: new Array(4).fill(0),
      pre_trace: new Array(16).fill(0),
      post_trace: new Array(4).fill(0),
      a_plus: 0.01, a_minus: 0.01,
    }),
    /local2d weights length 10 != outSize\*connSize \(36\)/
  );
});

test('computeDwForClass rejects unknown class', () => {
  assert.throws(() => M.computeDwForClass('UnknownRule', {}), /unknown learning class "UnknownRule"/);
});
